// ---------------------------------------------------------------------------
// File abstraction
// ---------------------------------------------------------------------------

/// Abstraction over an opened storage file that the service reads from.
///
/// This is parameterized so tests can substitute a different backing
/// implementation; the production type is [`MmapFile`].
pub trait StorageFile: Sized + Send + Sync + 'static {
    /// Open the file at `path`.
    fn open(path: &Path) -> std::io::Result<Self>;

    /// Total length of the file in bytes.
    fn len(&self) -> u64;

    /// Whether the file is empty.
    fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Read `length` bytes starting at `offset`.
    ///
    /// The caller must guarantee that `offset + length <= len()`.
    fn read(&self, offset: u64, length: u64) -> Vec<u8>;
}

/// Memory-mapped storage file used in production.
pub struct MmapFile {
    mmap: Option<memmap2::Mmap>,
    len: u64,
}

impl StorageFile for MmapFile {
    fn open(path: &Path) -> std::io::Result<Self> {
        let file = std::fs::File::open(path)?;
        let len = file.metadata()?.len();
        // Memory-mapping a zero-length file is not portable, so skip it.
        let mmap = if len == 0 {
            None
        } else {
            // SAFETY: the file is opened read-only and is only used for the
            // lifetime of this `MmapFile`. Concurrent external truncation could
            // in theory invalidate the mapping, but storage files are treated
            // as immutable for the duration of a read request.
            Some(unsafe { memmap2::Mmap::map(&file)? })
        };
        Ok(MmapFile { mmap, len })
    }

    fn len(&self) -> u64 {
        self.len
    }

    fn read(&self, offset: u64, length: u64) -> Vec<u8> {
        match &self.mmap {
            Some(mmap) => {
                let start = offset as usize;
                let end = start + length as usize;
                mmap[start..end].to_vec()
            }
            None => Vec::new(),
        }
    }
}

